import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface Note {
  id: number;
  targetType: string;
  targetId: number;
  text: string;
  /** When the note was written (ISO-8601 instant). */
  at: string;
}

@Injectable({ providedIn: 'root' })
export class NoteService {
  private readonly http = inject(HttpClient);

  /** A project's notes, newest first. */
  listForProject(projectId: number): Observable<Note[]> {
    return this.http.get<Note[]>(`/api/projects/${projectId}/notes`);
  }

  createForProject(projectId: number, text: string): Observable<Note> {
    return this.http.post<Note>(`/api/projects/${projectId}/notes`, { text });
  }

  /** An invoice's notes, newest first. */
  listForInvoice(projectId: number, invoiceId: number): Observable<Note[]> {
    return this.http.get<Note[]>(`/api/projects/${projectId}/invoices/${invoiceId}/notes`);
  }

  createForInvoice(projectId: number, invoiceId: number, text: string): Observable<Note> {
    return this.http.post<Note>(`/api/projects/${projectId}/invoices/${invoiceId}/notes`, { text });
  }
}
import { DatePipe } from '@angular/common';
import { Component, computed, inject, input, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { NoteService } from './note.service';

// The notes kept on a job, or on one of its invoices when an invoice is given: write a note and read
// them back, newest first.
@Component({
  selector: 'app-notes',
  imports: [ReactiveFormsModule, DatePipe],
  template: `
    <section [attr.aria-labelledby]="kind() + '-notes-heading'" [attr.data-testid]="kind() + '-notes'">
      <h2 [id]="kind() + '-notes-heading'">Notes</h2>

      <form [formGroup]="form" (ngSubmit)="submit()" data-testid="note-form" novalidate>
        <div>
          <label for="note-text">Note</label>
          <textarea
            id="note-text"
            rows="3"
            formControlName="text"
            maxlength="2000"
            data-testid="note-form-text"
            [attr.aria-invalid]="showTextError()"
            [attr.aria-describedby]="showTextError() ? 'note-text-error' : null"
          ></textarea>
          @if (showTextError()) {
            <p id="note-text-error" role="alert" data-testid="note-form-text-error">
              Note is required.
            </p>
          }
        </div>
        <button type="submit" data-testid="note-form-submit" [disabled]="saving()">Add note</button>
        @if (saveError()) {
          <p role="alert" data-testid="note-form-error">{{ saveError() }}</p>
        }
      </form>

      @if (notes.error()) {
        <p role="alert" [attr.data-testid]="kind() + '-notes-error'">Could not load the notes.</p>
      } @else if (notes.hasValue()) {
        @if (notes.value().length === 0) {
          <p [attr.data-testid]="kind() + '-notes-empty'">No notes on this {{ label() }} yet.</p>
        } @else {
          <ol
            class="notes"
            [attr.aria-label]="(kind() === 'invoice' ? 'Invoice' : 'Job') + ' notes, newest first'"
            [attr.data-testid]="kind() + '-note-list'"
          >
            @for (n of notes.value(); track n.id) {
              <li [attr.data-testid]="'note-row-' + n.id">
                <time [attr.datetime]="n.at" data-testid="note-at">{{ n.at | date: 'medium' }}</time>
                <p data-testid="note-text">{{ n.text }}</p>
              </li>
            }
          </ol>
        }
      }
    </section>
  `,
  styles: `
    .notes {
      list-style: none;
      padding: 0;
    }
    .notes p {
      margin: 0.25rem 0 1rem;
      white-space: pre-wrap;
    }
  `,
})
export class Notes {
  private readonly service = inject(NoteService);

  readonly projectId = input.required<number>();
  /** When given, the notes are the invoice's rather than the job's. */
  readonly invoiceId = input<number>();

  protected readonly kind = computed(() => (this.invoiceId() === undefined ? 'project' : 'invoice'));
  protected readonly label = computed(() => (this.kind() === 'invoice' ? 'invoice' : 'job'));

  protected readonly notes = rxResource({
    params: () => ({ projectId: this.projectId(), invoiceId: this.invoiceId() }),
    stream: ({ params }) =>
      params.invoiceId === undefined
        ? this.service.listForProject(params.projectId)
        : this.service.listForInvoice(params.projectId, params.invoiceId),
  });
  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    text: ['', [Validators.required, Validators.maxLength(2000)]],
  });

  protected showTextError(): boolean {
    const control = this.form.controls.text;
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    const text = this.form.getRawValue().text.trim();
    if (this.form.invalid || !text) {
      this.form.controls.text.setValue('');
      this.form.markAllAsTouched();
      return;
    }
    this.saving.set(true);
    this.saveError.set(null);
    const invoiceId = this.invoiceId();
    const request =
      invoiceId === undefined
        ? this.service.createForProject(this.projectId(), text)
        : this.service.createForInvoice(this.projectId(), invoiceId, text);
    request.subscribe({
      next: (created) => {
        this.notes.update((list) => [created, ...(list ?? [])]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the note. Please try again.');
        this.saving.set(false);
      },
    });
  }
}

